events.inlineCode:
// En itch.io el juego corre dentro de un iframe y el teclado sólo le llega cuando ese iframe
// tiene el foco. Al tocar "Run game", el botón de pantalla completa o cualquier parte de la
// página de afuera, el foco queda allá y las flechas no hacen nada. Los oyentes van sobre
// window, así que se instalan una sola vez y siguen andando en todas las escenas.
if (!window.toonariaFoco) {
  window.toonariaFoco = true;
  const recuperar = () => {
    // GDevelop descarta el teclado si el elemento enfocado no es el lienzo ni el body.
    const activo = document.activeElement;
    if (activo && activo !== document.body && activo.tagName !== "CANVAS") activo.blur();
    window.focus();
  };
  window.addEventListener("pointerdown", recuperar);
  // Entrar o salir de pantalla completa cambia el tamaño del iframe: es el momento de pedirlo.
  window.addEventListener("resize", recuperar);
  recuperar();
}
// Si el navegador no deja tomar el foco solo, el pie del título le pide al jugador un clic.
runtimeScene.getVariables().get("SinFoco").setNumber(document.hasFocus() ? 0 : 1);

// Leo todos los toques activos y no sólo el primero: con el cursor simulado por el toque
// no se podría mantener una flecha y saltar al mismo tiempo. Cada botón queda apretado si
// algún toque cae dentro de su caja, y "Recien" vale 1 sólo en el cuadro en que se apretó.
const estado = runtimeScene.getVariables().get("Tactil");
const entrada = runtimeScene.getGame().getInputManager();
const capa = runtimeScene.getLayer("Tactil");
const toques = entrada.getAllTouchIdentifiers();
for (const boton of runtimeScene.getObjects("BotonTactil")) {
  const tipo = boton.getVariables().get("Tipo").getAsString();
  let apretado = false;
  for (const id of toques) {
    const punto = capa.convertCoords(entrada.getTouchX(id), entrada.getTouchY(id));
    if (boton.insideObject(punto[0], punto[1])) {
      apretado = true;
      break;
    }
  }
  const antes = estado.getChild(tipo).getAsNumber();
  estado.getChild(tipo + "Recien").setNumber(apretado && antes === 0 ? 1 : 0);
  estado.getChild(tipo).setNumber(apretado ? 1 : 0);
  boton.setOpacity(apretado ? 255 : 140);
}
